# ------------------------------------------------------------
# NORMALIZATSIYA
# ------------------------------------------------------------

CYR_TO_LAT = str.maketrans({
    "а": "a", "б": "b", "в": "v", "г": "g", "д": "d",
    "е": "e", "ё": "yo", "ж": "j", "з": "z", "и": "i",
    "й": "y", "к": "k", "қ": "q", "л": "l", "м": "m",
    "н": "n", "о": "o", "п": "p", "р": "r", "с": "s",
    "т": "t", "у": "u", "ў": "o", "ф": "f", "х": "x",
    "ҳ": "h", "ц": "s", "ч": "ch", "ш": "sh", "ъ": "",
    "ь": "", "э": "e", "ю": "yu", "я": "ya"
})

def norm(text):
    text = str(text or "").lower().strip()
    text = text.translate(CYR_TO_LAT)
    text = (
        text.replace("ʻ", "")
        .replace("ʼ", "")
        .replace("’", "")
        .replace("‘", "")
        .replace("`", "")
        .replace("'", "")
    )
    text = re.sub(r"[^a-z0-9]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()

# ------------------------------------------------------------
# HUJJATLARNI YUKLASH
# ------------------------------------------------------------

def load_kb():
    try:
        with open(KB_FILE, "r", encoding="utf-8-sig") as f:
            data = json.load(f)
    except json.JSONDecodeError as e:
        logging.error("KB JSON xatosi: %s; fayl=%s", e, KB_FILE)
        return []
    except Exception as e:
        logging.exception("KB yuklash xatosi: %s", e)
        return []

    raw_docs = data.get("documents", data.get("docs", [])) if isinstance(data, dict) else data
    if not isinstance(raw_docs, list):
        raw_docs = []

    docs = []

    for item in raw_docs:
        if not isinstance(item, dict):
            continue

        title = str(item.get("title", "")).strip()
        # KB schema uses document_number/canonical_document_number; older
        # versions of this bot expected a field called number. Support both.
        number = str(
            item.get("document_number")
            or item.get("canonical_document_number")
            or item.get("number")
            or ""
        ).strip()
        date = str(item.get("date", "")).strip()
        source = str(item.get("source_file", "")).strip()
        text = str(item.get("text", item.get("content", ""))).strip()
        aliases = item.get("aliases", item.get("search_aliases", []))
        if not isinstance(aliases, list):
            aliases = []
        # Preserve all explicit KB aliases and add the canonical number.
        if number and number not in aliases:
            aliases = [number] + list(aliases)

        if not text:
            continue

        docs.append({
            "title": title,
            "number": number,
            "date": date,
            "source_file": source,
            "aliases": [str(x) for x in aliases],
            "text": text,
            "ntitle": norm(title),
            "nnumber": norm(number),
            "nsource": norm(source),
            "naliases": [norm(x) for x in aliases],
            "ntext": norm(text),
        })

    if not docs:
        raise RuntimeError("Knowledge base ichida hujjatlar topilmadi")

    logging.info("Knowledge base: %s ta hujjat", len(docs))
    return docs

