_846_EMBEDDED_GZ_B64 = """"""


def _load_embedded_846():
    try:
        raw = gzip.decompress(base64.b64decode(_846_EMBEDDED_GZ_B64))
        data = json.loads(raw.decode("utf-8"))
        objs = data.get("objects", []) if isinstance(data, dict) else []
        if isinstance(objs, list) and len(objs) >= 1000:
            logging.info("846 embedded ro'yxat yuklandi: %s ta obyekt", len(objs))
            return objs
    except Exception as e:
        logging.exception("846 embedded JSON xatosi: %s", e)
    return []

def load_846_objects():
    """Load the structured 846 list locally; if unavailable/corrupt, fetch the
    exact committed GitHub file once. Only app.py needs replacement.
    """
    path = os.path.join(BASE_DIR, "846_full_extracted.json")
    try:
        if os.path.isfile(path) and os.path.getsize(path) > 1000:
            with open(path, "r", encoding="utf-8-sig", errors="ignore") as fh:
                data = json.load(fh)
            objs = data.get("objects", []) if isinstance(data, dict) else []
            if isinstance(objs, list) and len(objs) >= 1000:
                logging.info("846 structured ro'yxat yuklandi: %s ta obyekt", len(objs))
                return objs
            logging.warning("846 local JSON obyektlar soni kutilganidan kam: %s",
                            len(objs) if isinstance(objs, list) else 0)
    except Exception as e:
        logging.warning("846 local JSON xatosi: %s", e)

    url = "https://raw.githubusercontent.com/maqsudvaxobov1-maker/madaniymeros-ai-bot/main/846_full_extracted.json"
    try:
        logging.info("846 structured JSON GitHub manbasidan yuklanmoqda...")
        req = urllib.request.Request(url, headers={"User-Agent": "Madaniy-Meros-AI/16"})
        with urllib.request.urlopen(req, timeout=30) as resp:
            raw = resp.read().decode("utf-8-sig", errors="strict")
        data = json.loads(raw)
        objs = data.get("objects", []) if isinstance(data, dict) else []
        if isinstance(objs, list) and len(objs) >= 1000:
            logging.info("846 GitHub fallback yuklandi: %s ta obyekt", len(objs))
            return objs
        logging.error("846 GitHub fallback noto'g'ri: obyektlar=%s",
                      len(objs) if isinstance(objs, list) else 0)
    except Exception as e:
        logging.exception("846 GitHub fallback xatosi: %s", e)

    # Final fallback: use the embedded full list in app.py.
    return _load_embedded_846()

_846_OBJECTS = load_846_objects()

def _846_norm(s):
    x = norm(str(s or ""))
    return re.sub(r"[^0-9a-zа-яёғқҳўъ\s]", " ", x).strip()

def _846_category(x):
    x = _846_norm(x)
    if "arxe" in x: return "Археология ёдгорликлари"
    if "arxitektura" in x: return "Архитектура ёдгорликлари"
    if "monumental" in x and "sanat" in x: return "Монументал санъат ёдгорликлари"
    if "diqqatga" in x: return "Диққатга сазовор жойлар"
    return x

def lookup_846_structured(question):
    if not _846_OBJECTS:
        return None
    q = _846_norm(question)

    # Direct official position lookup, e.g. “846 1-ilovada 7-raqam”.
    mpos = re.search(r"(?:\b|^)(\d{1,5})\s*(?:raqam(?:dagi|da)?|pozitsiya(?:si)?|tartib(?:\s*raqami)?)(?:\b|$)", q)
    if not mpos:
        mpos = re.search(r"\b(\d{1,5})\s*[- ]?raqam", q)
    if mpos:
        pos = int(mpos.group(1))
        hits = [r for r in _846_OBJECTS if str(r.get("tartib_raqami", "")).strip() == str(pos)]
        if hits:
            return ("FOUND", hits[0]) if len(hits) == 1 else ("LIST", hits)

    # Region aliases are normalized through _846_norm(), so both Latin and
    # Cyrillic user questions are handled consistently.
    regions = {
        "samarqand": "Самарқанд вилояти",
        "buxoro": "Бухоро вилояти",
        "andijon": "Андижон вилояти",
        "toshkent": "Тошкент вилояти",
        "fargona": "Фарғона вилояти",
        "namangan": "Наманган вилояти",
        "xorazm": "Хоразм вилояти",
        "qashqadaryo": "Қашқадарё вилояти",
        "surxondaryo": "Сурходарё вилояти",
        "surxodaryo": "Сурходарё вилояти",
        "jizzax": "Жиззах вилояти",
        "sirdaryo": "Сирдарё вилояти",
        "navoiy": "Навоий вилояти",
        "qoraqalpogiston": "Қорақалпоғистон Республикаси",
        "qoraqalpogiston respublikasi": "Қорақалпоғистон Республикаси",
    }
    region = next((v for k, v in regions.items() if k in q), None)

    cat = None
    if any(x in q for x in ("arxeolog", "qazishma", "qazish")):
        cat = "Археология ёдгорликлари"
    elif "arxitektura" in q:
        cat = "Архитектура ёдгорликлари"
    elif "monumental" in q:
        cat = "Монументал санъат ёдгорликлари"
    elif "diqqatga sazovor" in q:
        cat = "Диққатга сазовор жойлар"

    # Words that describe the request itself, not an object name.
    stop = {
        "846", "son", "qaror", "karor", "qarorning", "ilova", "ilovasi",
        "boyicha", "boyicha", "milliy", "royxat", "ruyxat", "royxatda",
        "royxatida", "royxatning", "bor", "bormi", "obyekt", "obekt",
        "obyekti", "obyektlar", "obyektlari", "obyektlarini", "obyektning", "obyektni", "obektlar", "obektlari", "obektlarini", "yodgorlik", "yodgorliklar", "yodgorligi", "yodgorliklari", "yodgorliklarini",
        "pozitsiya", "pozitsiyasi", "manzil", "manzili", "qaysi", "nomi",
        "viloyati", "viloyatidagi", "viloyatida", "viloyat", "tuman", "tumani",
        "shahar", "shahridagi", "dagi", "dan", "ga", "uchun", "kerak",
        "arxeologiya", "arxeologik", "qazishma", "qazish", "ruxsat",
        "topildi", "ta", "obyektlari", "obektlari", "men", "siz", "menga",
        "chiqar", "chiqaring", "korsat", "korsating", "top", "toping", "qaysilar", "qaysi",
        "toliq", "tolig", "raqam", "raqamdagi", "boyicha", "ber", "bering",
        "royxatini", "royxatlar", "royxatni", "royxatdan", "hammasi", "barchasi",
        "nechta", "soni", "tartib", "tartibi", "qilib", "qilish", "berish", "chiqarib", "korsatib", "topib", "aytib", "yozib", "keltirib", "ilovada", "ilovasida", "ilovaga", "ilovadan", "ilovadagi", "keltirilgan", "keltirilganmi", "raqamida", "raqamda", "pozitsiyada", "mavjudmi", "degan", "deganmi", "qayd", "qilingan", "qaysi", "ko‘rsatilgan", "kursatilgan", "ayting", "ko‘rsat", "ko‘rsating"
    }
    # Remove pure numbers and request boilerplate. Region/category tokens are
    # also excluded so a regional/category list query has no false object token.
    region_tokens = set()
    if region:
        for k, v in regions.items():
            if v == region:
                region_tokens.update(k.split())
        region_tokens.update(_846_norm(region).split())
    cat_tokens = set(_846_norm(cat or "").split())
    raw_tokens = [
        t for t in q.split()
        if len(t) > 2 and not t.isdigit() and t not in stop
        and t not in region_tokens and t not in cat_tokens
    ]

    # Regional/category list requests often contain action verbs such as "qilib".
    # They are request boilerplate, not object-name tokens.
    if region and cat and not raw_tokens:
        arr = [r for r in _846_OBJECTS if _846_norm(r.get("viloyat")) == _846_norm(region) and _846_category(r.get("toifa")) == cat]
        arr.sort(key=sort_key) if "sort_key" in locals() else arr.sort(key=lambda r: (int(re.search(r"\d+", str(r.get("tartib_raqami", ""))).group()) if re.search(r"\d+", str(r.get("tartib_raqami", ""))) else 10**9, str(r.get("tartib_raqami", ""))))
        return ("LIST", arr)
    candidates = []
    # First priority: exact normalized object-name phrase. This prevents a
    # query such as “Afrosiyob qal’asi qaysi tartib raqamida” from returning
    # unrelated objects that happen to contain only one of the words.
    query_object_phrase = " ".join(raw_tokens).strip()
    exact_phrase_hits = []
    for r in _846_OBJECTS:
        if region and _846_norm(r.get("viloyat")) != _846_norm(region):
            continue
        if cat and _846_category(r.get("toifa")) != cat:
            continue
        name_blob = _846_norm(r.get("obyekt_toliq_nomi", ""))
        address_blob = _846_norm(r.get("obyekt_manzili", ""))
        if query_object_phrase and query_object_phrase in name_blob:
            exact_phrase_hits.append(r)
        elif query_object_phrase and query_object_phrase in address_blob:
            exact_phrase_hits.append(r)

    if exact_phrase_hits:
        exact_phrase_hits.sort(key=sort_key) if "sort_key" in locals() else exact_phrase_hits.sort(key=lambda r: int(re.search(r"\d+", str(r.get("tartib_raqami", ""))).group()) if re.search(r"\d+", str(r.get("tartib_raqami", ""))) else 10**9)
        if len(exact_phrase_hits) == 1:
            return ("FOUND", exact_phrase_hits[0])
        return ("LIST", exact_phrase_hits)

    for r in _846_OBJECTS:
        if region and _846_norm(r.get("viloyat")) != _846_norm(region):
            continue
        if cat and _846_category(r.get("toifa")) != cat:
            continue
        blob = _846_norm(
            f"{r.get('obyekt_toliq_nomi','')} {r.get('obyekt_manzili','')}"
        )
        score = sum(1 for t in raw_tokens if t in blob)
        if raw_tokens and score == len(raw_tokens):
            candidates.append(r)

    def sort_key(r):
        raw = str(r.get("tartib_raqami", "")).strip()
        m = re.search(r"\d+", raw)
        return (int(m.group()) if m else 10**9, raw)

    if candidates:
        candidates.sort(key=sort_key)
        if len(candidates) == 1 and raw_tokens:
            return ("FOUND", candidates[0])
        return ("LIST", candidates)

    # Region/category list request: return ALL matching records, sorted by the
    # official list number. This prevents gaps such as 1-6, 9, 970.
    if region and cat and not raw_tokens:
        arr = [
            r for r in _846_OBJECTS
            if _846_norm(r.get("viloyat")) == _846_norm(region) and _846_category(r.get("toifa")) == cat
        ]
        arr.sort(key=sort_key)
        return ("LIST", arr)

    return None

