STOP_WORDS = {
    "va", "ham", "bu", "shu", "uchun", "bilan", "qanday", "qaysi",
    "nima", "qachon", "menga", "kerak", "bering", "ber", "haqida",
    "boyicha", "bo‘yicha", "siz", "men", "ning", "ni", "ga", "da",
    "dan", "mi", "mumkin", "uchun", "boladi", "bo‘ladi"
}

def keywords(question):
    words = re.findall(r"[a-z0-9]+", norm(question))
    return list(dict.fromkeys(
        w for w in words
        if len(w) >= 2 and w not in STOP_WORDS
    ))

def chunks(text, size=3500, overlap=450):
    if len(text) <= size:
        return [text]

    result = []
    start = 0

    while start < len(text):
        end = min(start + size, len(text))
        result.append(text[start:end])

        if end >= len(text):
            break

        start = end - overlap

    return result

def document_number_match(number, doc):
    if not number:
        return False

    n = norm(number)

    fields = [
        doc["nnumber"],
        doc["ntitle"],
        doc["nsource"],
        *doc["naliases"],
    ]

    if n == "269 ii":
        return any("269 ii" in x for x in fields)

    return any(re.search(rf"\b{re.escape(n)}\b", x) for x in fields)

def search_kb(question, limit=14):
    q = norm(question)
    keys = keywords(question)
    number = detect_number(question)
    topics = detect_topics(question)

    found = []

    all_docs = DOCUMENTS + [
        {
            "title": x["title"],
            "number": "",
            "date": "",
            "source_file": x["source_file"],
            "aliases": [],
            "text": x["text"],
            "ntitle": norm(x["title"]),
            "nnumber": "",
            "nsource": norm(x["source_file"]),
            "naliases": [],
            "ntext": norm(x["text"]),
        }
        for x in OFFICIAL_SOURCES
    ]

    for doc in all_docs:
        doc_bonus = 0

        if number and document_number_match(number, doc):
            doc_bonus += 140

        title_lower = doc["ntitle"]

        if "kengash" in topics and "ilmiy ekspert" in title_lower:
            doc_bonus += 80

        if "milliy_royxat" in topics and "846" in title_lower:
            doc_bonus += 120

        for chunk in chunks(doc["text"]):
            nchunk = norm(chunk)
            score = doc_bonus

            if len(q) >= 10 and q in nchunk:
                score += 100

            matched_keys = 0
            for key in keys:
                if key in nchunk:
                    score += 4
                    matched_keys += 1
                if key in title_lower:
                    score += 10
                if key in doc["nsource"]:
                    score += 8

            topic_words = {
                "ekspertiza": ["ekspert", "ekspertiza", "xulosa"],
                "kengash": ["kengash", "kotib", "yig‘ilish", "yigilish"],
                "qurilish": ["qurilish", "rekonstruksiya", "loyiha", "buzish"],
                "muhofaza": ["muhofaza", "qo‘riqlanadigan", "tegrasi", "saqlash"],
                "arxeologiya": ["arxeolog", "arxeologiya", "qazish", "ochiq varaq", "ruxsatnoma"],
                "muzey": ["muzey", "fond", "katalog", "kolleksiya"],
                "kadastr": ["kadastr", "reyestr", "ma’lumotnoma"],
                "milliy_royxat": ["milliy ro‘yxat", "milliy royxat", "846"],
                "restavratsiya": ["restavratsiya", "konservatsiya", "ta’mirlash"],
                "madaniy_boylik": ["madaniy boylik", "olib chiqish", "auksion", "realizatsiya"],
                "litsenziya": ["litsenziya"],
                "ruxsatnoma": ["ruxsatnoma", "ruxsat"],
                "unesco": ["unesco", "umumjahon", "bufer"],
                "davlat_xizmati": ["davlat xizmati", "my gov", "yidxp", "xizmat"],
                "tolov": ["to‘lov", "tolov", "bhm"],
                "muddat": ["muddat", "ish kuni", "kun", "bajarish"],
                "nomoddiy": ["nomoddiy", "an’ana", "xalq ijodi"],
            }

            for topic in topics:
                for word in topic_words.get(topic, []):
                    nw = norm(word)
                    if nw in nchunk:
                        score += 12

            if matched_keys == 0 and doc_bonus == 0:
                continue

            found.append({
                "score": score,
                "title": doc["title"],
                "source": doc["source_file"],
                "text": chunk,
            })

    found.sort(key=lambda x: x["score"], reverse=True)

    # Bir xil matnlarni olib tashlash
    unique = []
    seen = set()

    for item in found:
        key = (item["title"], item["text"][:500])
        if key in seen:
            continue
        seen.add(key)
        unique.append(item)

    return unique[:limit]


