def exact_answer(question):
    q = norm(question)
    topics = detect_topics(question)
    number = detect_number(question)

    # V27 PROFESSIONAL GUARDRAILS -------------------------------------------------
    # Keep distinct legal processes separate: historical-cultural expertise,
    # Council review, administrative services, permits, licences and archaeology.
    # These deterministic answers intentionally avoid inventing a mandatory chain.

    # 0) Generic document-identification answers must not fall through to
    # object lookup/LLM.
    if number == "846" and any(x in q for x in ["nima", "nomi", "toliq nomi", "qaror nima"]):
        return """Vazirlar Mahkamasining 2019-yil 4-oktabrdagi 846-son qarori — “Moddiy madaniy merosning ko‘chmas mulk obyektlari milliy ro‘yxatini tasdiqlash to‘g‘risida”.

Manba: VMQ 846-son, 04.10.2019."""
    if number == "295" and any(x in q for x in ["nima", "nomi", "toliq nomi", "qaror nima"]):
        return """Vazirlar Mahkamasining 2024-yil 20-maydagi 295-son qarori — madaniy meros sohasidagi Ilmiy-ekspert kengashi va tegishli tartiblarni belgilovchi qaror.

Manba: VMQ 295-son, 20.05.2024."""
    if number == "512" and any(x in q for x in ["nima", "nomi", "toliq nomi", "qaror nima"]):
        return """Vazirlar Mahkamasining 2025-yil 13-avgustdagi 512-son qarori — “Madaniy meros sohasiga oid ma’muriy reglamentlarni tasdiqlash to‘g‘risida”.

Manba: VMQ 512-son, 13.08.2025."""

    # 1) Historical-cultural expertise: 30-day ceiling is NOT the same as
    # Council's 7/14-day review period or a 512-service deadline.
    if "ekspertiza" in q and any(x in q for x in [
        "muddat", "necha kun", "qancha kun", "qachongacha", "30 kun", "30 kundan"
    ]):
        return """Tarixiy-madaniy ekspertiza o‘tkazish muddati 30 kundan oshmasligi kerak.

Bu muddatni Ilmiy-ekspert Kengashining 7/14 ish kunlik ko‘rib chiqish muddati yoki 512-son ma’muriy xizmatining alohida xizmat muddati bilan aralashtirmaslik kerak.

Manba: Vazirlar Mahkamasining 2002-yil 29-iyuldagi 269-son qarori bilan tasdiqlangan Nizom, 18-band."""

    # 2) Current licensing rule for conservation/restoration activity.
    # VMQ 80, 3-ilova: conservation, restoration, repair, adaptation and
    # restoration of immovable tangible cultural heritage are licensable
    # activities for legal entities; Agency is the licensing authority.
    if any(x in q for x in ["litsenziya", "lisenziya", "litsenziyalash", "litsenziya kerak", "litsenziya olish"]) and any(x in q for x in [
        "restavratsiya", "restavrasiya", "konservatsiya", "konservasiya", "asrash", "ta'mirlash", "tamirlash", "moslashtirish", "tiklash", "madaniy meros"
    ]):
        return """Moddiy madaniy merosning ko‘chmas mulk obyektlarini asrashga doir faoliyat litsenziyalanadi. Litsenziya talabgori — yuridik shaxs, litsenziyalovchi organ — O‘zbekiston Respublikasi Madaniy meros agentligi.

Litsenziyalanadigan asrash faoliyatiga obyektni konservatsiyalash, restavratsiya qilish, ta’mirlash, zamonaviy foydalanishga moslashtirish va tiklash kiradi.

Litsenziya toifalari:
- I toifa — mahalliy ahamiyatga ega obyektlarda asrashga doir ishlar;
- II toifa — respublika va mahalliy ahamiyatdagi obyektlarda asrashga doir ishlar.

To‘lov va muddat:
- arizani ko‘rib chiqish yig‘imi — 1 BHM;
- litsenziya berilganligi uchun davlat boji — I toifa 20 BHM, II toifa 40 BHM;
- arizani ko‘rib chiqish muddati — 7 ish kuni;
- litsenziya muddati — cheklanmagan.

Muhim: litsenziya obyektni asrashga doir ishlarni bajarish uchun zarur ruxsatnoma o‘rnini avtomatik bosmaydi. Litsenziya talablari va tegishli ish uchun ruxsatnoma talablari alohida tekshiriladi. Arxeologiya yodgorligini konservatsiya qilishda tegishli ruxsatnomaga ega arxeologni jalb etish talabi ham mavjud.

Manba: Vazirlar Mahkamasining 2022-yil 21-fevraldagi 80-son qarori bilan tasdiqlangan Yagona nizomning 3-ilovasi — “Moddiy madaniy merosning ko‘chmas mulk obyektlarini asrashga doir faoliyatni litsenziyalash PASPORTI”, amaldagi tahrir."""

    # 3) Restoration / conservation: permit and Council conclusion are separate
    # legal processes. Do not invent a universal chain.
    if any(x in q for x in ["restavratsiya", "restavrasiya", "konservatsiya", "konservasiya"]) and any(x in q for x in [
        "kerak", "hujjat", "ruxsat", "ruxsatnoma", "qanday", "nima talab", "talab qilin"
    ]):
        return """Konservatsiya yoki restavratsiya ishlarida talab qilinadigan hujjatlar ish turi, obyektning maqomi va loyiha doirasiga qarab belgilanadi. Madaniy meros agentligining rasmiy xizmatlar portalida tadqiqot, konservatsiya va restavratsiya ishlari uchun ruxsatnoma xizmati mavjud.

Muhim farq:
- ruxsatnoma — alohida ma’muriy xizmat/huquqiy ruxsat;
- Ilmiy-ekspert Kengashi xulosasi — Kengash vakolatiga kiradigan loyiha yoki masalani ko‘rib chiqish natijasi;
- litsenziya — faqat qonunchilikda litsenziyalanadigan faoliyatga nisbatan talab qilinadi;
- arxeologik ochiq varaq va arxeologik ruxsatnoma — arxeologik qidiruv/qazish ishlari uchun alohida institutlar.

Shuning uchun “har qanday restavratsiya uchun avtomatik ravishda litsenziya + Kengash xulosasi + arxeologik ruxsatnoma kerak” degan umumiy xulosa chiqarib bo‘lmaydi.

Manba: VMQ 512-son, 13.08.2025; O‘RQ-229-son Qonun, 3-modda; Ilmiy-ekspert Kengashi Nizomi."""

    # 3) Protected-zone construction: Council involvement depends on the type
    # of project and applicable status; do not turn it into a universal permit.
    if any(x in q for x in ["muhofaza tegrasi", "muhofaza zonasi", "qo‘riqlanadigan tegra", "qoriqlanadigan tegra"]) and any(x in q for x in [
        "qurilish", "yangi bino", "bino qur", "qurmoq", "qurish"
    ]):
        return """Muhofaza tegrasida qurilish masalasi obyektning huquqiy maqomi, tasdiqlangan muhofaza tegrasi, ish turi va loyiha xususiyatiga qarab baholanadi.

Ilmiy-ekspert Kengashi Nizomida madaniy meros obyektlari va ularning muhofaza tegralaridagi qurilish, yer qazish, yer tuzish, melioratsiya va boshqa tegishli loyihalarni ko‘rib chiqish vakolati nazarda tutilgan. Biroq bundan “muhofaza tegrasidagi har qanday qurilish uchun avtomatik ravishda ikkita Kengashning roziligi shart” degan xulosa chiqarilmaydi.

Amaliy tartibda avval obyekt maqomi va muhofaza tegrasi aniqlanadi, so‘ng aynan shu loyiha uchun talab qilinadigan xulosa, kelishuv, ruxsatnoma va boshqa hujjatlar belgilanadi.

Manba: VMQ 295-son, 20.05.2024, 2-ilova; muhofaza tegralariga oid amaldagi normativ hujjatlar."""

    # 4) Cadastral administrative service: do not fabricate a Council -> Agency
    # order -> cadastral registration chain unless the applicable regulation says so.
    if any(x in q for x in ["kadastrga", "kadastriga", "kadastrdan"]) and any(x in q for x in ["kirit", "chiqar", "qanday", "nima kerak", "hujjat", "muddat", "tolov", "yigim", "yig‘im"]):
        return """Moddiy madaniy meros obyektini davlat kadastriga kiritish yoki undan chiqarish bo‘yicha alohida davlat xizmati mavjud.

YIDXPdagi amaldagi xizmat ma’lumotiga ko‘ra:
- xizmat muddati — 27 kun;
- hujjatlar — xizmat kartochkasida talab etilmaydi;
- YIDXP orqali yig‘im — 0,5 BHM.

Bu ma’lumotni Ilmiy-ekspert Kengashining ichki ko‘rib chiqish muddatlari yoki Kengash Nizomidagi boshqa to‘lovlar bilan avtomatik qo‘shib hisoblash mumkin emas.

Shuningdek, faqat Kengash xulosasi asosida “albatta Agentlik buyrug‘i chiqariladi” degan umumiy xulosa chiqarilmaydi — yakuniy natija amaldagi kadastr ma’muriy reglamentiga muvofiq belgilanadi.

Manba: VMQ 512-son, 13.08.2025; YIDXPning amaldagi davlat xizmati ma’lumotlari."""

