def answer_question(question):
    # 1. Exact, source-backed answers first.
    exact = exact_answer(question)
    if exact:
        return exact

    number = detect_number(question)
    topics = detect_topics(question)

    # 2. Dynamic/statistical questions get a trusted official web check.
    online_context = ""
    if should_online_search(question):
        try:
            online_result = search_official(question, max_sources=5)
            online_context = format_context(online_result)
            if online_context:
                logging.info("Rasmiy onlayn manbalar topildi: %s", len(online_result.get("sources", [])))
        except Exception:
            logging.exception("Rasmiy onlayn qidiruv xatosi")

    results = search_kb(question, limit=18)

    # 2. 846-specific protection: never infer an object/position without
    #    the actual full national-list source.
    if is_846_question(question) and is_specific_846_lookup(question):
        has_full_list = any(
            (
                "846" in norm(r.get("title", ""))
                and len(r.get("text", "")) > 5000
            )
            for r in results
        )
        if not has_full_list and _846_DOC is None:
            return (
                "846-son qarorning milliy ro‘yxatidagi aniq obyektni "
                "tasdiqlash uchun 846-son qarorning to‘liq ro‘yxat matni "
                "kerak. Ishchi bilim bazasida to‘liq ro‘yxat aniqlanmagani "
                "sababli obyekt nomi yoki pozitsiyasini taxmin qilmayman.\n\n"
                f"Manba: {NATIONAL_LIST_SOURCE}"
            )

    # 3. If a user explicitly names a document number but the retrieved
    #    context does not actually contain that number, do not let the LLM
    #    manufacture a citation.
    if number and not has_source_backed_number(results, number):
        return (
            f"Саволда {number}-сон ҳужжат кўрсатилган, аммо тақдим этилган "
            f"билим базасида шу рақамга тегишли тасдиқланган матн топилмади. "
            f"Шу сабабли ҳужжатнинг мазмуни ёки бандини тахмин қилиб бермайман."
        )

    if not results and not online_context:
        return (
            "Тақдим этилган билим базасида бу саволга етарли аниқ "
            "маълумот топилмади ва ишончли расмий онлайн манба ҳам топилмади. "
            "Шу сабабли фактни тахмин қилиб бермайман."
        )

    context = build_strict_context(results) if results else ""
    if online_context:
        context += "\n\n" + online_context

    # 4. Stronger system instruction appended at runtime.
    strict_suffix = """V14 QAT'IY HUQUQIY NAZORAT:
- Faqat ISHONCHLI KONTEKSTdagi matn bilan asosla.
- Kontekstda yo‘q raqam, sana, band, to‘lov, muddat, vakolat yoki ruxsat turini yaratma.
- Qonun, qaror, nizom, xulosa, kelishuv va ruxsatnomani bir xil hujjat deb hisoblama.
- 269-II Qonun, 269-son qaror/Nizom, 295-son, 119-son, 265-son, 649-son va 846-sonni alohida ajrat.
- Agar ikki hujjat vakolat yoki tartib bo‘yicha farq qilsa, qaysi biri amalda ekanini taxmin qilma; manbada aniq asos bo‘lmasa, bu cheklovni ochiq ayt.
- “Amaliyotda”, “ehtimol”, “mumkin” kabi iboralar bilan normativ xulosani almashtirma.
- Arxeologik qazishma bo‘yicha maxsus ruxsatnoma, ochiq varaq va Kengash xulosasi tushunchalarini alohida ko‘rsat.
- CCTV yoki boshqa texnik montajni manbada bevosita norma bo‘lmasa avtomatik ravishda qurilish deb tasniflama.
- 846-son ro‘yxatdagi obyekt faqat to‘liq ro‘yxat manbasida aynan tasdiqlangan bo‘lsa “bor” deb aytiladi. Topilmagan obyektni “yo‘q” yoki “madaniy meros emas” deb xulosa qilma.
- “Manba 1”, “Manba 2” kabi ichki texnik belgilarni foydalanuvchiga chiqarmasdan, hujjatning nomi, sanasi, raqami va bandini yoz.
- Manba yetarli bo‘lmasa: “Taqdim etilgan bilim bazasida bu savolga yetarli aniq ma’lumot topilmadi” deb ayt.
- Tarixiy-madaniy ekspertiza muddati: 269-son qaror Nizomining 18-bandidagi 30 kunlik chegarani Kengashning 7/14 ish kunlik muddati va 512-son xizmat muddatidan alohida ko‘rsat.
- Ruxsatnoma, litsenziya, ekspertiza xulosasi, Kengash qarori va ma’muriy xizmat natijasini bitta hujjat yoki bitta bosqich deb birlashtirma.
- Restavratsiya/konservatsiya bo‘yicha litsenziyani faqat litsenziyalanadigan faoliyat ekanligi manbada tasdiqlanganda talab sifatida ko‘rsat.
- Muhofaza tegrasidagi har qanday qurilish uchun avtomatik “ikki bosqichli Kengash roziligi” xulosasini bermang; avval loyiha va obyekt maqomini ajrating.
- Kadastr xizmatida YIDXPning amaldagi 27 kun/0,5 BHM ma’lumotlarini Kengash Nizomidagi 50 foiz BHM to‘lovi bilan avtomatik birlashtirmang.
- 269-II 2001-yilgi norma bilan 2026-yildagi amaliy vakolatni ajrating; keyingi hujjatlar mavjud bo‘lsa, eskirgan vakolatni hozirgi holat sifatida qat’iy aytmang.
"""
    context = context + "\n\n" + strict_suffix

    return ask_openai(question, context)

